        [Parameter(Mandatory)][string]$Operation,
        [Parameter(Mandatory)][bool]$PriorExisted,
        [AllowNull()][AllowEmptyString()][string]$PriorContent
    )

    $record = [ordered]@{
        version = 1
        operation = $Operation
        priorExisted = $PriorExisted
        priorContent = $PriorContent
        createdAt = [DateTimeOffset]::UtcNow.ToString('o')
    }
    $json = ConvertTo-Json -InputObject ([pscustomobject]$record) -Depth 8
    Write-AtomicFile -Path (Get-UndoRecordPath -Path $Path) -Content "$json`n"
}

